/**
 * Fixture manifest types + paths (G-014/G-005).
 *
 * The WAVs are generated by scripts/demo/generate-fixtures.mjs with ffmpeg and
 * are gitignored (*.wav); fixtures.json is committed and is the single source of
 * truth for expected segment boundaries and the scripted transcripts the mock
 * ASR replays.
 */
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import manifest from "./fixtures/fixtures.json";

export interface FixturePartial {
  atMs: number;
  text: string;
}

export interface FixtureSegment {
  startMs: number;
  endMs: number;
  amplitude?: number;
  text: string;
  partials?: FixturePartial[];
}

export interface FixtureDef {
  id: string;
  wav: string;
  durationMs: number;
  role: string;
  segments: FixtureSegment[];
}

export interface FixtureManifest {
  sampleRate: number;
  description: string;
  fixtures: FixtureDef[];
}

export const FIXTURE_MANIFEST = manifest as FixtureManifest;

export const DEMO_DIR = import.meta.dirname;
export const FIXTURE_DIR = path.join(DEMO_DIR, "fixtures");
/** Repo root: artifacts/craft-vita/src/demo -> ../../../.. */
export const REPO_ROOT = path.resolve(DEMO_DIR, "..", "..", "..", "..");
export const EVIDENCE_DIR = path.join(REPO_ROOT, "docs", "evidence", "demo");
export const GENERATOR_SCRIPT = path.join(REPO_ROOT, "scripts", "demo", "generate-fixtures.mjs");

export function getFixture(id: string): FixtureDef {
  const fixture = FIXTURE_MANIFEST.fixtures.find((f) => f.id === id);
  if (!fixture) throw new Error(`Unknown fixture "${id}". Known: ${FIXTURE_MANIFEST.fixtures.map((f) => f.id).join(", ")}`);
  return fixture;
}

export function fixtureWavPath(fixture: FixtureDef): string {
  return path.join(FIXTURE_DIR, fixture.wav);
}

export function allFixturesExist(): boolean {
  return FIXTURE_MANIFEST.fixtures.every((f) => existsSync(fixtureWavPath(f)));
}

export function loadFixtureWavBytes(fixture: FixtureDef): Uint8Array {
  return new Uint8Array(readFileSync(fixtureWavPath(fixture)));
}
